import subprocess
def run(args):
    p=subprocess.run(["timeout","3","./executable"]+args, input=b'', capture_output=True)
    print(f"{args} => {p.stdout!r} err:{p.stderr[:200]!r}")
for off in ['0.0','0.1','0.4','0.5','0.6','1.0','1.4','1.5','1.6','2.5','3.5','-0.5','-1.5','10.5']:
    run(['-n','4','-o',off,'echo $COUNT'])
print("--- countby int variations offset 1.5")
for by in ['1','2','3','0','-1']:
    run(['-n','4','-o','1.5','--count-by='+by,'echo $COUNT'])
print("--- countby float offset int")
for by in ['1.5','2.5','0.5']:
    run(['-n','4','-o','2','-b',by,'echo $COUNT'])
print("--- offset float by float")
for off,by in [('0.5','1.0'),('0.5','2.0'),('1.5','1.0')]:
    run(['-n','4','-o',off,'-b',by,'echo $COUNT'])
PY"}

