                let secs = number
                    .checked_mul(60)
                    .ok_or_else(|| "number is too large".to_string())?;
                Duration::new(secs, 0)
            }
            "hours" | "hour" | "hr" | "hrs" | "h" => {
                let secs = number
                    .checked_mul(3_600)
                    .ok_or_else(|| "number is too large".to_string())?;
                Duration::new(secs, 0)
            }
