                let secs = number
                    .checked_mul(86_400)
                    .ok_or_else(|| "number is too large".to_string())?;
                Duration::new(secs, 0)
            }
            "weeks" | "week" | "w" => {
                let secs = number
                    .checked_mul(604_800)
                    .ok_or_else(|| "number is too large".to_string())?;
                Duration::new(secs, 0)
            }
            "months" | "month" | "M" => {
                let secs = number
                    .checked_mul(2_630_016)
