                Duration::new(secs, 0)
            }
            "years" | "year" | "y" => {
                let secs = number
                    .checked_mul(31_557_600)
                    .ok_or_else(|| "number is too large".to_string())?;
                Duration::new(secs, 0)
            }
            _ => {
                return Err(format!("unknown unit at {}-{}", start, end));
            }
