                    return Err(format!("invalid character at {}", pos));
                }
            }
        }
    }

    match state {
        State::Number => {
            if have_number {
                Err(format!("unknown unit at {}-{}", src.len(), src.len()))
            } else if !any_component {
                Err("value was empty".to_string())
            } else {
                Ok(total)
            }
        }
        State::Unit => {
            total = add_component(total, number, &unit, unit_start, unit_end)?;
            Ok(total)
        }
    }
}
