        4 | 6 | 9 | 11 => 30,
        2 if leap => 29,
        2 => 28,
        _ => unreachable!(),
    };
    if day < 1 || day > days_in_month || hour > 23 || minute > 59 || second > 60 {
        return Err("numeric component is out of range".to_string());
    }
    if year < 1970 {
        return Err("numeric component is out of range".to_string());
    }

    let rest = &bytes[19..];
    let mut nanos: u32 = 0;
    if !rest.is_empty() && rest != b"Z" {
        if rest[0] != b'.' {
            return Err("timestamp format is invalid".to_string());
        }
        let mut fraction_digits: usize = 0;
        let mut value: u32 = 0;
        let mut index = 1;
        while index < rest.len() {
            let byte = rest[index];
            if byte.is_ascii_digit() {
