                }
                fraction_digits += 1;
            } else if byte == b'Z' && index == rest.len() - 1 {
                // Optional zone marker; handled on loop exit.
            } else {
                return Err("bad character where digit is expected".to_string());
            }
            index += 1;
        }
        if fraction_digits > 0 {
            if fraction_digits < 9 {
                value *= 10_u32.pow((9 - fraction_digits) as u32);
            }
            nanos = value;
        }
    }

    let days = days_from_civil(year as i64, month as i64, day as i64);
    let seconds =
        days as u64 * 86_400 + hour as u64 * 3_600 + minute as u64 * 60 + second as u64;
    Ok(UNIX_EPOCH + Duration::new(seconds, nanos))
