use crate::duration::parse_duration;
use crate::timestamp::parse_timestamp;
use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Validator {
    None,
    Float,
    Duration,
    Regex,
    Timestamp,
}

#[derive(Clone, Copy, Debug)]
pub struct Spec {
    pub id: &'static str,
    pub long: &'static str,
    pub short: Option<char>,
    pub value_name: Option<&'static str>,
    pub default: Option<&'static str>,
    pub validator: Validator,
}

impl Spec {
    pub fn is_option(&self) -> bool {
        self.value_name.is_some()
    }
    fn display(&self) -> String {
        match self.value_name {
            Some(value) => format!("--{} <{}>", self.long, value),
            None => format!("--{}", self.long),
        }
    }
}

pub const SPECS: &[Spec] = &[
    Spec { id: "count_by", long: "count-by", short: Some('b'), value_name: Some("count_by"), default: Some("1"), validator: Validator::Float },
    Spec { id: "every", long: "every", short: Some('e'), value_name: Some("every"), default: Some("1us"), validator: Validator::Duration },
    Spec { id: "ffor", long: "for", short: None, value_name: Some("ffor"), default: None, validator: Validator::None },
    Spec { id: "for_duration", long: "for-duration", short: Some('d'), value_name: Some("for_duration"), default: None, validator: Validator::Duration },
    Spec { id: "num", long: "num", short: Some('n'), value_name: Some("num"), default: None, validator: Validator::Float },
    Spec { id: "offset", long: "offset", short: Some('o'), value_name: Some("offset"), default: Some("0"), validator: Validator::Float },
    Spec { id: "until_contains", long: "until-contains", short: Some('c'), value_name: Some("until_contains"), default: None, validator: Validator::None },
    Spec { id: "until_error", long: "until-error", short: Some('r'), value_name: Some("until_error"), default: None, validator: Validator::None },
    Spec { id: "until_match", long: "until-match", short: Some('m'), value_name: Some("until_match"), default: None, validator: Validator::Regex },
    Spec { id: "until_time", long: "until-time", short: Some('t'), value_name: Some("until_time"), default: None, validator: Validator::Timestamp },
    Spec { id: "error_duration", long: "error-duration", short: Some('D'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "help", long: "help", short: Some('h'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "only_last", long: "only-last", short: Some('l'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "stdin", long: "stdin", short: Some('i'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "summary", long: "summary", short: None, value_name: None, default: None, validator: Validator::None },
    Spec { id: "until_changes", long: "until-changes", short: Some('C'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "until_fail", long: "until-fail", short: Some('f'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "until_same", long: "until-same", short: Some('S'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "until_success", long: "until-success", short: Some('s'), value_name: None, default: None, validator: Validator::None },
    Spec { id: "version", long: "version", short: Some('V'), value_name: None, default: None, validator: Validator::None },
];

const DEFAULT_IDS: &[&str] = &["count_by", "every", "offset"];
const DID_YOU_MEAN_ORDER: &[&str] = &[
    "error-duration",
    "help",
    "only-last",
    "stdin",
    "summary",
    "until-changes",
    "until-same",
    "until-fail",
    "until-success",
    "version",
    "count-by",
    "every",
    "for",
    "for-duration",
    "num",
    "offset",
    "until-contains",
    "until-error",
    "until-match",
    "until-time",
];

pub fn spec_by_id(id: &str) -> &'static Spec {
    SPECS.iter().find(|spec| spec.id == id).unwrap()
}
pub fn spec_by_long(long: &str) -> Option<&'static Spec> {
    SPECS.iter().find(|spec| spec.long == long)
}
fn spec_by_short(short: char) -> Option<&'static Spec> {
    SPECS.iter().find(|spec| spec.short == Some(short))
}

#[derive(Default, Clone, Debug)]
struct ArgData {
    occurrences: usize,
    values: Vec<String>,
}

#[derive(Debug)]
pub struct Parsed {
    pub bin: String,
    data: HashMap<&'static str, ArgData>,
    pub inputs: Vec<String>,
}

impl Parsed {
    pub fn has(&self, id: &str) -> bool {
        self.data.contains_key(id)
    }
    pub fn value(&self, id: &str) -> Option<&str> {
        let data = self.data.get(id)?;
        if let Some(value) = data.values.first() {
            Some(value.as_str())
        } else {
            spec_by_id(id).default
        }
    }
}

pub enum Outcome {
    Parsed(Parsed),
    Help(String),
    Version,
    Error(String),
}

struct State {
    bin: String,
    data: HashMap<&'static str, ArgData>,
    used_order: Vec<&'static str>,
}

impl State {
    fn new(bin: String) -> Self {
        State {
            bin,
            data: HashMap::new(),
            used_order: Vec::new(),
        }
    }
    fn mark(&mut self, spec: &'static Spec) {
        if !self.data.contains_key(spec.id) {
            self.used_order.push(spec.id);
        }
        self.data.entry(spec.id).or_default().occurrences += 1;
    }
    fn add_value(&mut self, spec: &'static Spec, value: String) {
        self.data.entry(spec.id).or_default().values.push(value);
    }
    fn used_ids(&self) -> Vec<&'static str> {
        self.used_order.clone()
    }
    fn usage_for(&self, mut ids: Vec<&'static str>) -> String {
        ids.sort_by_key(|id| spec_by_id(id).long);
        ids.dedup();
        if ids.is_empty() {
            return format!("{} [FLAGS] [OPTIONS] [input]...", self.bin);
        }
        let parts: Vec<String> = ids
            .iter()
            .map(|id| spec_by_id(id).display())
            .collect();
        format!("{} {}", self.bin, parts.join(" "))
    }
    fn unknown_error(
        &self,
        display: &str,
        suggestion: Option<&'static Spec>,
    ) -> String {
        let mut ids = self.used_ids();
        if let Some(spec) = suggestion {
            ids.push(spec.id);
        }
        let usage = self.usage_for(ids);
        let mut text = format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",
            display
        );
        if let Some(spec) = suggestion {
            text.push_str(&format!(
                "\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?\n",
                spec.long
            ));
        }
        text.push_str(&format!(
            "\nUSAGE:\n    {}\n\nFor more information try --help\n",
            usage
        ));
        text
    }
    fn validation_usage(&self) -> String {
        let mut ids: Vec<&'static str> = DEFAULT_IDS.to_vec();
        ids.extend(self.used_ids());
        self.usage_for(ids)
    }
}

fn is_arg_like(token: &str) -> bool {
    token == "--"
        || token.starts_with("--")
        || (token.starts_with('-') && token.chars().count() > 1)
}

fn validate_value(spec: &Spec, value: &str) -> Result<(), String> {
    match spec.validator {
        Validator::None => Ok(()),
        Validator::Float => value
            .parse::<f64>()
            .map(|_| ())
            .map_err(|error| error.to_string()),
        Validator::Duration => parse_duration(value).map(|_| ()),
        Validator::Regex => regex::Regex::new(value)
            .map(|_| ())
            .map_err(|error| error.to_string()),
        Validator::Timestamp => parse_timestamp(value).map(|_| ()),
    }
}

pub fn parse_args(argv: Vec<String>) -> Outcome {
    let bin = bin_name(argv.first().map(String::as_str));
    let tokens: Vec<String> = argv.into_iter().skip(1).collect();
    let mut state = State::new(bin.clone());
    let mut inputs: Vec<String> = Vec::new();
    let mut after_separator = false;
    let mut index = 0usize;

    while index < tokens.len() {
        let token = tokens[index].clone();
        if after_separator {
            inputs.push(token);
            index += 1;
            continue;
        }
        if token == "--" {
            after_separator = true;
            index += 1;
            continue;
        }
        if token.starts_with("--") {
            // Clap 2 removes all leading dashes from a long argument.
            let rest = token.trim_start_matches('-');
            let (name, attached) = match rest.split_once('=') {
                Some((name, value)) => (name, Some(value.trim_start_matches('=').to_string())),
                None => (rest, None),
            };
            if name.is_empty() {
                return Outcome::Error(state.unknown_error("--", None));
            }
            let spec = match spec_by_long(name) {
                Some(spec) => spec,
                None => {
                    let suggestion = did_you_mean(name);
                    return Outcome::Error(
                        state.unknown_error(&format!("--{}", name), suggestion),
                    );
                }
            };
            if spec.id == "help" {
                return Outcome::Help(help_text(&bin));
            }
            if spec.id == "version" {
                return Outcome::Version;
            }
            state.mark(spec);
            if spec.is_option() {
                if let Some(value) = attached {
                    state.add_value(spec, value);
                } else if index + 1 < tokens.len() && !is_arg_like(&tokens[index + 1]) {
                    index += 1;
                    state.add_value(spec, tokens[index].clone());
                }
            }
            index += 1;
            continue;
        }
        if token.starts_with('-') && token.chars().count() > 1 {
            let chars: Vec<(usize, char)> = token.char_indices().skip(1).collect();
            let mut consumed_token = false;
            for (byte_index, short) in chars {
                let spec = match spec_by_short(short) {
                    Some(spec) => spec,
                    None => {
                        return Outcome::Error(
                            state.unknown_error(&format!("-{}", short), None),
                        );
                    }
                };
                if spec.id == "help" {
                    return Outcome::Help(help_text(&bin));
                }
                if spec.id == "version" {
                    return Outcome::Version;
                }
                state.mark(spec);
                if spec.is_option() {
                    let remainder = &token[byte_index + short.len_utf8()..];
                    if !remainder.is_empty() {
                        state.add_value(spec, remainder.trim_start_matches('=').to_string());
