fn did_you_mean(value: &str) -> Option<&'static Spec> {
    let mut best: Option<(f64, &'static Spec)> = None;
    for long in DID_YOU_MEAN_ORDER {
        let spec = spec_by_long(long).unwrap();
        let confidence = jaro_winkler(value, spec.long);
        if confidence > 0.8 && (best.is_none() || confidence > best.unwrap().0) {
            best = Some((confidence, spec));
        }
    }
    best.map(|(_, spec)| spec)
}

fn jaro_winkler(first: &str, second: &str) -> f64 {
    let first_chars: Vec<char> = first.chars().collect();
    let second_chars: Vec<char> = second.chars().collect();
    let jaro = jaro(&first_chars, &second_chars);
    let prefix = first_chars
        .iter()
        .zip(second_chars.iter())
        .take(4)
        .take_while(|(a, b)| a == b)
        .count();
    jaro + (prefix as f64 * 0.1 * (1.0 - jaro))
}

fn jaro(first: &[char], second: &[char]) -> f64 {
    if first.is_empty() && second.is_empty() {
        return 1.0;
    }
    if first.is_empty() || second.is_empty() {
        return 0.0;
    }
    if first == second {
        return 1.0;
    }
    let search_range = (first.len().max(second.len()) / 2).saturating_sub(1);
    let mut first_matches = vec![false; first.len()];
    let mut second_matches = vec![false; second.len()];
    let mut matches = 0usize;
    for (i, first_char) in first.iter().enumerate() {
        let start = i.saturating_sub(search_range);
        let end = (i + search_range + 1).min(second.len());
        for j in start..end {
            if !second_matches[j] && *first_char == second[j] {
                first_matches[i] = true;
                second_matches[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut transpositions = 0usize;
    let mut second_index = 0usize;
    for (i, first_char) in first.iter().enumerate() {
        if !first_matches[i] {
            continue;
        }
        while !second_matches[second_index] {
            second_index += 1;
        }
        if *first_char != second[second_index] {
            transpositions += 1;
        }
        second_index += 1;
    }
    let matches = matches as f64;
    (matches / first.len() as f64
        + matches / second.len() as f64
        + (matches - (transpositions / 2) as f64) / matches)
        / 3.0
}

pub fn help_text(bin: &str) -> String {
    format!(
        "loop 0.6.1\n\
Rich Jones <miserlou@gmail.com>\n\
UNIX's missing `loop` command\n\
\n\
USAGE:\n\
    {} [FLAGS] [OPTIONS] [input]...\n\
\n\
FLAGS:\n\
    -D, --error-duration    Exit with timeout error code on duration\n\
    -h, --help              Prints help information\n\
    -l, --only-last         Only print the output of the last execution of the command\n\
    -i, --stdin             Read from standard input\n\
        --summary           Provide a summary\n\
    -C, --until-changes     Keep going until the output changes\n\
    -f, --until-fail        Keep going until the command exit status is non-zero\n\
    -S, --until-same        Keep going until the output changes\n\
    -s, --until-success     Keep going until the command exit status is zero\n\
    -V, --version           Prints version information\n\
\n\
OPTIONS:\n\
    -b, --count-by <count_by>                Amount to increment the counter by [default: 1]\n\
    -e, --every <every>                      How often to iterate. ex., 5s, 1h1m1s1ms1us [default: 1us]\n\
