use std::io::{self, BufRead, BufReader, IsTerminal, Seek, SeekFrom};
use std::process::{self, Command, Stdio};
use std::thread;
use std::time::{Duration, Instant, SystemTime};

mod cli;
mod duration;
mod timestamp;

use cli::Outcome;
use duration::parse_duration;
use timestamp::parse_timestamp;

fn main() {
    let start_time = Instant::now();
    let parsed = match cli::parse_args(env::args().collect()) {
        Outcome::Parsed(parsed) => parsed,
        Outcome::Help(text) => {
            print!("{}", text);
            return;
        }
        Outcome::Version => {
            println!("loop 0.6.1");
            return;
        }
        Outcome::Error(text) => {
            eprint!("{}", text);
            process::exit(1);
        }
    };
    let count_by_value = parsed.value("count_by").unwrap_or("1").to_string();
    let offset_value = parsed.value("offset").unwrap_or("0").to_string();
    let every_value = parsed.value("every").unwrap_or("1us").to_string();
    let count_by: f64 = count_by_value.parse().unwrap();
    let offset: f64 = offset_value.parse().unwrap();
    let places = decimal_places(&count_by_value);
    let every: Duration = parse_duration(&every_value).unwrap();
    let mut items: Vec<String> = Vec::new();
    if let Some(values) = parsed.value("ffor") {
        for item in values.split(',') {
            items.push(item.to_string());
        }
    }
    if parsed.has("stdin") || !io::stdin().is_terminal() {
        for result in io::stdin().lock().lines() {
          let line = result.unwrap();
            items.push(line);
        }
    }
    let num: Option<u64> = parsed.value("num").map(|value| value.parse::<f64>().unwrap() as u64);
    let for_duration: Option<Duration> = parsed.value("for_duration").map(|value| parse_duration(value).unwrap());
    let until_time: Option<SystemTime> = parsed.value("until_time").map(|value| parse_timestamp(value).unwrap());
    let until_contains: Option<String> = parsed.value("until_contains").map(|s| s.to_string());
    let until_error: Option<String> = parsed.value("until_error").map(|s| s.to_string());
    let until_match: Option<regex::Regex> = parsed.value("until_match").map(|value| regex::Regex::new(value).unwrap());
    let command = parsed.inputs.join(" ");
    if command.is_empty() {
        println!("No command supplied, exiting.");
        return;
    }
    let mut outfile = tempfile::tempfile().unwrap();
    let limit: Option<u64> = num.or_else(|| if items.is_empty() { None } else { Some(items.len() as u64) });
    let mut count = offset - count_by;
    let mut actual_count: u64 = 0;
    let mut total_runs: u64 = 0;
    let mut successes: u64 = 0;
    let mut failures: Vec<i32> = Vec::new();
    let mut first_output: Option<String> = None;
    let mut last_output = String::new();
    let mut result_code = 0;
    loop {
        if let Some(limit) = limit {
            if actual_count >= limit {
                break;
            }
        }
        if let Some(limit_duration) = for_duration {
            if start_time.elapsed() >= limit_duration {
                if parsed.has("error_duration") {
                    result_code = 124;
                }
                break;
            }
        }
        if let Some(time) = until_time {
            if SystemTime::now() >= time {
                break;
            }
        }
        let iteration_start = Instant::now();
        count += count_by;
        env::set_var("COUNT", format!("{:.*}", places, count));
        env::set_var("ACTUALCOUNT", actual_count.to_string());
        if !items.is_empty() {
            let item = if (actual_count as usize) < items.len() {
                &items[actual_count as usize]
            } else {
                items.last().unwrap()
            };
            env::set_var("ITEM", item);
        }
        outfile.set_len(0).unwrap();
        outfile.seek(SeekFrom::Start(0)).unwrap();
        let stdout_file = outfile.try_clone().unwrap();
        let stderr_file = outfile.try_clone().unwrap();
        let mut reader = BufReader::new(&outfile);
        let spawn_result = Command::new("sh").arg("-c").arg(&command).stdout(Stdio::from(stdout_file)).stderr(Stdio::from(stderr_file)).spawn();
        let mut child = spawn_result
                      .map_err(|error| SpawnError::IoError(error))
                      .unwrap();
        let status = child.wait().unwrap();
        reader.seek(SeekFrom::Start(0)).unwrap();
        let mut entire_output = String::new();
        loop { let mut line = String::new();
                reader.read_line(&mut line).expect("read failed");
            if line.is_empty() {
                break;
            }
            entire_output.push_str(&line);
        }
        total_runs += 1;
        let status_code = status.code().unwrap_or(99);
        if status_code == 0 {
            successes += 1;
        } else {
            failures.push(status_code);
        }
        if parsed.has("only_last") {
            last_output = entire_output.clone();
        } else {
            print_output(&entire_output);
        }
        if first_output.is_none() {
            first_output = Some(entire_output.clone());
        }
        let mut should_stop = false;
        if parsed.has("until_success") && status_code == 0 {
            should_stop = true;
        }
        if parsed.has("until_fail") && status_code != 0 {
            should_stop = true;
        }
        if let Some(target) = &until_error {
            match target.parse::<u32>() {
                Ok(target_code) => {
                    if status.code().map(|code| code as u32) == Some(target_code) {
                        should_stop = true;
                    }
                }
                Err(_) => {
                    if status_code != 0 {
                        should_stop = true;
                    }
                }
            }
        }
        if let Some(needle) = &until_contains {
            for line in entire_output.lines() {
                if line.contains(needle.as_str()) {
                    should_stop = true;
                }
            }
        }
        if let Some(pattern) = &until_match {
            for line in entire_output.lines() {
                if pattern.is_match(line) {
                    should_stop = true;
                }
            }
        }
        if actual_count > 0 {
            if let Some(first) = &first_output {
                if parsed.has("until_changes") && entire_output != *first {
                    should_stop = true;
                }
                if parsed.has("until_same") && entire_output == *first {
                    should_stop = true;
                }
            }
        }
        actual_count += 1;
        if should_stop {
            break;
        }
        let elapsed = iteration_start.elapsed();
        if elapsed < every {
            thread::sleep(every - elapsed);
        }
    }
    if parsed.has("only_last") {
        print_output(&last_output);
    }
    if parsed.has("summary") {
        println!("Total runs:\t{}", total_runs);
        println!("Successes:\t{}", successes);
        if failures.is_empty() {
            println!("Failures:\t0");
        } else {
            let codes: Vec<String> = failures.iter().map(|code| code.to_string()).collect();
            println!("Failures:\t{} ({})", failures.len(), codes.join(", "));
        }
    }
    if result_code != 0 {
        process::exit(result_code);
    }
}

#[derive(Debug)]
enum SpawnError {
    IoError(io::Error),
}

fn print_output(output: &str) {
    for line in output.lines() {
        println!("{}", line);
    }
}

fn decimal_places(count_by: &str) -> usize {
    match count_by.find('.') {
        Some(position) => count_by[position + 1..]
            .chars()
            .take_while(|c| c.is_ascii_digit())
            .count(),
        None => 0,
    }
}
