            failures.push(status_code);
        }
        if parsed.has("only_last") {
            last_output = entire_output.clone();
        } else {
            print_output(&entire_output);
        }
        if first_output.is_none() {
            first_output = Some(entire_output.clone());
        }
        let mut should_stop = false;
        if parsed.has("until_success") && status_code == 0 {
            should_stop = true;
        }
        if parsed.has("until_fail") && status_code != 0 {
            should_stop = true;
        }
        if let Some(target) = &until_error {
            match target.parse::<u32>() {
                Ok(target_code) => {
                    if status.code().map(|code| code as u32) == Some(target_code) {
                        should_stop = true;
                    }
                }
                Err(_) => {
                    if status_code != 0 {
                        should_stop = true;
                    }
                }
            }
        }
        if let Some(needle) = &until_contains {
            for line in entire_output.lines() {
                if line.contains(needle.as_str()) {
                    should_stop = true;
                }
            }
        }
        if let Some(pattern) = &until_match {
            for line in entire_output.lines() {
                if pattern.is_match(line) {
                    should_stop = true;
                }
            }
        }
        if actual_count > 0 {
            if let Some(first) = &first_output {
                if parsed.has("until_changes") && entire_output != *first {
                    should_stop = true;
                }
                if parsed.has("until_same") && entire_output == *first {
                    should_stop = true;
                }
            }
        }
        actual_count += 1;
        if should_stop {
            break;
        }
        let elapsed = iteration_start.elapsed();
        if elapsed < every {
            thread::sleep(every - elapsed);
        }
    }
    if parsed.has("only_last") {
        print_output(&last_output);
    }
    if parsed.has("summary") {
        println!("Total runs:\t{}", total_runs);
        println!("Successes:\t{}", successes);
        if failures.is_empty() {
            println!("Failures:\t0");
        } else {
            let codes: Vec<String> = failures.iter().map(|code| code.to_string()).collect();
            println!("Failures:\t{} ({})", failures.len(), codes.join(", "));
        }
    }
    if result_code != 0 {
        process::exit(result_code);
    }
}

#[derive(Debug)]
enum SpawnError {
    IoError(io::Error),
}

fn print_output(output: &str) {
    for line in output.lines() {
        println!("{}", line);
    }
}

fn decimal_places(count_by: &str) -> usize {
    match count_by.find('.') {
        Some(position) => count_by[position + 1..]
            .chars()
            .take_while(|c| c.is_ascii_digit())
            .count(),
        None => 0,
    }
}
