// Compatibility checks for the older regular-expression syntax accepted
// by the original program.  The current `regex` crate accepts a few
// constructs that the older one rejected (and vice versa only in error
// wording); the checks here reject those constructs with the older
// diagnostics before/after delegating the remaining work to `regex`.

#[derive(Clone, Copy, Default)]
struct Flags {
    extended: bool,
}

pub struct Check {
    old_error: Option<String>,
    empty_alternation: bool,
}

pub fn validate(pattern: &str) -> Result<(), String> {
    let check = check_pattern(pattern);
    match regex::Regex::new(pattern) {
        Ok(_) => {
            if let Some(error) = check.old_error {
                Err(error)
            } else if check.empty_alternation {
                Err("alternations cannot currently contain empty sub-expressions".to_string())
            } else {
                Ok(())
            }
        }
        Err(error) => {
            if let Some(old_error) = check.old_error {
                Err(old_error)
            } else {
                Err(error.to_string())
            }
        }
    }
}

fn format_parse_error(pattern: &str, position: usize, span: usize, message: &str) -> String {
    format!(
        "regex parse error:\n    {}\n    {}{}\nerror: {}",
        pattern,
        " ".repeat(position),
        "^".repeat(span.max(1)),
        message
    )
}

struct Parser {
    chars: Vec<char>,
    position: usize,
    old_error: Option<String>,
    empty_alternation: bool,
    depth: usize,
    aborted: bool,
}

pub fn check_pattern(pattern: &str) -> Check {
    if pattern.contains('\n') || pattern.contains('\r') {
        return Check {
            old_error: None,
            empty_alternation: false,
        };
    }
    let mut parser = Parser {
        chars: pattern.chars().collect(),
        position: 0,
        old_error: None,
        empty_alternation: false,
        depth: 0,
        aborted: false,
    };
    let mut flags = Flags::default();
    parser.parse_alternation(&mut flags, false);
    Check {
        old_error: parser.old_error,
        empty_alternation: parser.empty_alternation,
    }
}

impl Parser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.position).copied()
    }
    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.position + offset).copied()
    }
    fn bump(&mut self) -> Option<char> {
        let current = self.peek()?;
        self.position += 1;
        Some(current)
    }
    fn record_old_error(&mut self, pattern_position: usize, span: usize, message: &str) {
        if self.old_error.is_none() {
            let pattern: String = self.chars.iter().collect();
            self.old_error = Some(format_parse_error(
                &pattern,
                pattern_position,
                span,
                message,
            ));
        }
    }

    // Parses branches until ')' (when in_group) or the end of input.
    // Returns whether the last branch contained an expression.
