        chars: pattern.chars().collect(),
        position: 0,
        old_error: None,
        empty_alternation: false,
        depth: 0,
        aborted: false,
    };
    let mut flags = Flags::default();
    parser.parse_alternation(&mut flags, false);
    Check {
        old_error: parser.old_error,
        empty_alternation: parser.empty_alternation,
    }
}

impl Parser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.position).copied()
    }
    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.position + offset).copied()
    }
    fn bump(&mut self) -> Option<char> {
        let current = self.peek()?;
        self.position += 1;
        Some(current)
    }
    fn record_old_error(&mut self, pattern_position: usize, span: usize, message: &str) {
        if self.old_error.is_none() {
            let pattern: String = self.chars.iter().collect();
            self.old_error = Some(format_parse_error(
                &pattern,
                pattern_position,
                span,
                message,
            ));
        }
    }

    // Parses branches until ')' (when in_group) or the end of input.
    // Returns whether the last branch contained an expression.
    fn parse_alternation(&mut self, flags: &mut Flags, in_group: bool) -> bool {
        let mut branches: Vec<bool> = Vec::new();
        loop {
            let branch_has = self.parse_sequence(flags, in_group);
            branches.push(branch_has);
            if self.aborted {
                break;
            }
            match self.peek() {
                Some('|') => {
                    self.position += 1;
                    continue;
                }
                _ => break,
            }
        }
        if branches.len() > 1 && branches.iter().any(|has| !has) {
            self.empty_alternation = true;
        }
        *branches.last().unwrap_or(&false)
    }

    fn parse_sequence(&mut self, flags: &mut Flags, _in_group: bool) -> bool {
        let mut has_expression = false;
        loop {
            if self.aborted {
                break;
            }
            let Some(current) = self.peek() else {
                break;
            };
            if current == '|' || current == ')' {
                break;
            }
            if flags.extended {
                if current.is_whitespace() {
                    self.position += 1;
                    continue;
                }
                if current == '#' {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.position += 1;
                    }
                    continue;
                }
            }
            if self.parse_atom_and_quantifier(flags) {
                has_expression = true;
            }
        }
        has_expression
    }

    fn parse_atom_and_quantifier(&mut self, flags: &mut Flags) -> bool {
        let atom_has = self.parse_atom(flags);
        let mut quantified = false;
        loop {
            match self.peek() {
                Some('*') | Some('+') | Some('?') => {
                    self.position += 1;
                    quantified = true;
                    // A following '?' is the lazy marker; consuming it
                    // as another quantifier is harmless for this check.
                }
                Some('{') => {
                    if !self.try_consume_counted_quantifier() {
                        break;
                    }
                    quantified = true;
                }
                _ => break,
            }
        }
        atom_has || quantified
    }

    fn try_consume_counted_quantifier(&mut self) -> bool {
        let mut index = self.position + 1;
        let mut saw_digit = false;
        let mut saw_comma = false;
        while let Some(c) = self.chars.get(index).copied() {
            if c.is_ascii_digit() {
                saw_digit = true;
                index += 1;
            } else if c == ',' && !saw_comma {
                saw_comma = true;
                index += 1;
            } else {
                break;
            }
        }
        if self.chars.get(index).copied() == Some('}') && (saw_digit || saw_comma) {
            self.position = index + 1;
            true
        } else {
            false
        }
    }

    fn parse_atom(&mut self, flags: &mut Flags) -> bool {
        let Some(current) = self.bump() else {
            return false;
        };
        match current {
            '(' => self.parse_group(flags),
            '[' => {
                self.parse_class();
                true
            }
            '\\' => {
                self.parse_escape();
                true
            }
            _ => true,
        }
    }

    fn parse_group(&mut self, flags: &mut Flags) -> bool {
        if self.depth > 128 {
            self.aborted = true;
            return true;
        }
        if self.peek() == Some('?') {
            self.position += 1;
            match self.peek() {
                Some('<') => {
                    let less_than_position = self.position;
                    // A modern named capture group.  The older syntax
                    // only understood (?P<name>...) and reports the
                    // '<' as an unrecognized flag.
                    let mut index = self.position + 1;
                    let mut saw_name = false;
                    while let Some(c) = self.chars.get(index).copied() {
                        if c == '>' {
                            break;
                        }
                        if !(c.is_alphanumeric() || c == '_' || c == '.' || c == '[' || c == ']') {
                            break;
                        }
                        saw_name = true;
                        index += 1;
                    }
                    if saw_name && self.chars.get(index).copied() == Some('>') {
                        self.record_old_error(less_than_position, 1, "unrecognized flag");
                        self.position = index + 1;
                        self.depth += 1;
                        let mut inner_flags = *flags;
                        let result = self.parse_alternation(&mut inner_flags, true);
                        self.depth -= 1;
                        if self.peek() == Some(')') {
                            self.position += 1;
                        }
                        return result;
                    }
                    true
                }
                Some('P') => {
                    self.position += 1;
                    if self.peek() == Some('<') {
                        self.position += 1;
                        while let Some(c) = self.peek() {
                            self.position += 1;
                            if c == '>' {
                                break;
                            }
                        }
                        self.depth += 1;
                        let mut inner_flags = *flags;
                        let result = self.parse_alternation(&mut inner_flags, true);
                        self.depth -= 1;
                        if self.peek() == Some(')') {
                            self.position += 1;
                        }
                        result
                    } else if self.peek() == Some('=') {
                        while let Some(c) = self.bump() {
                            if c == ')' {
                                break;
                            }
                        }
                        true
                    } else {
                        true
                    }
                }
                Some(':') => {
                    self.position += 1;
                    self.depth += 1;
                    let mut inner_flags = *flags;
                    let result = self.parse_alternation(&mut inner_flags, true);
                    self.depth -= 1;
                    if self.peek() == Some(')') {
                        self.position += 1;
                    }
                    result
                }
                _ => {
                    // A flag directive such as (?i), (?-x) or a scoped
                    // flag group such as (?i:...).
                    let mut scoped_flags = *flags;
                    let mut negated = false;
                    let mut is_scoped = false;
                    loop {
                        match self.peek() {
                            Some(':') => {
                                self.position += 1;
                                is_scoped = true;
                                break;
                            }
                            Some(')') => {
                                self.position += 1;
                                break;
                            }
                            Some('-') => {
                                negated = true;
                                self.position += 1;
                            }
                            Some(c) if c.is_ascii_alphabetic() => {
                                if c == 'R' {
                                    let position = self.position;
                                    self.record_old_error(position, 1, "unrecognized flag");
                                }
                                if c == 'x' {
                                    scoped_flags.extended = !negated;
                                }
                                self.position += 1;
                            }
                            _ => break,
                        }
                    }
                    if is_scoped {
                        self.depth += 1;
                        let result = self.parse_alternation(&mut scoped_flags, true);
                        self.depth -= 1;
                        if self.peek() == Some(')') {
                            self.position += 1;
                        }
                        result
                    } else {
                        // A directive changes the flags of the
                        // enclosing group for what follows.
                        flags.extended = scoped_flags.extended;
                        false
                    }
                }
            }
        } else {
            self.depth += 1;
            let mut inner_flags = *flags;
            let result = self.parse_alternation(&mut inner_flags, true);
            self.depth -= 1;
            if self.peek() == Some(')') {
                self.position += 1;
            }
            result
        }
    }

    fn parse_class(&mut self) {
        let mut depth = 1usize;
        if self.peek() == Some('^') {
            self.position += 1;
        }
        if self.peek() == Some(']') {
            self.position += 1;
        }
        while let Some(current) = self.peek() {
            match current {
                '\\' => {
                    self.position += 2;
                }
                '[' => {
                    depth += 1;
                    self.position += 1;
                    if self.peek() == Some('^') {
                        self.position += 1;
                    }
                    if self.peek() == Some(']') {
                        self.position += 1;
                    }
                }
                ']' => {
                    self.position += 1;
                    depth -= 1;
                    if depth == 0 {
                        return;
                    }
                }
                _ => {
                    self.position += 1;
                }
            }
            if self.position >= self.chars.len() {
                return;
            }
        }
    }

    fn parse_escape(&mut self) {
        let Some(escaped) = self.bump() else {
            return;
        };
        if escaped == 'b' && self.peek() == Some('{') {
            let names = ["start-half", "end-half", "start", "end"];
            let rest_start = self.position + 1;
            for name in names {
                let name_chars: Vec<char> = name.chars().collect();
                if self.chars.len() >= rest_start + name_chars.len() + 1
                    && self.chars[rest_start..rest_start + name_chars.len()] == name_chars[..]
                    && self.chars[rest_start + name_chars.len()] == '}'
                {
                    let position = rest_start;
                    self.record_old_error(
                        position,
                        1,
                        "repetition quantifier expects a valid decimal",
                    );
                    self.position = rest_start + name_chars.len() + 1;
                    return;
                }
            }
        }
        if escaped == 'p' || escaped == 'P' {
            if self.peek() == Some('{') {
                while let Some(c) = self.bump() {
                    if c == '}' {
                        break;
                    }
                }
            }
        }
    }
}
