// ---------- character class emptiness ----------

type IntervalSet = Vec<(u32, u32)>;

fn normalize(mut intervals: IntervalSet) -> IntervalSet {
    intervals.sort();
    let mut result: IntervalSet = Vec::new();
    for (start, end) in intervals {
        if start > end {
            continue;
        }
        if let Some((_, last_end)) = result.last_mut() {
            if start <= *last_end || start == *last_end + 1 {
                if end > *last_end {
                    *last_end = end;
                }
                continue;
            }
        }
        result.push((start, end));
    }
    result
}

fn union_sets(first: IntervalSet, second: IntervalSet) -> IntervalSet {
    let mut all = first;
    all.extend(second);
    normalize(all)
}

fn intersect_sets(first: &IntervalSet, second: &IntervalSet) -> IntervalSet {
    let mut result = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < first.len() && j < second.len() {
        let start = first[i].0.max(second[j].0);
        let end = first[i].1.min(second[j].1);
        if start <= end {
            result.push((start, end));
        }
        if first[i].1 < second[j].1 {
            i += 1;
        } else {
            j += 1;
        }
    }
    result
}

fn complement_set(set: &IntervalSet) -> IntervalSet {
    let mut result = Vec::new();
    let mut next = 0u32;
    for &(start, end) in set {
        if start > next {
            result.push((next, start - 1));
        }
        next = next.max(end.saturating_add(1));
        if next > 0x10FFFF {
            return result;
        }
    }
    if next <= 0x10FFFF {
        result.push((next, 0x10FFFF));
    }
    result
}

struct ClassParser {
    chars: Vec<char>,
    position: usize,
}

impl ClassParser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.position).copied()
    }
    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.position + offset).copied()
    }

    fn parse_outer(&mut self) -> Option<IntervalSet> {
        if self.peek() != Some('[') {
            return None;
        }
        self.position += 1;
        let negated = if self.peek() == Some('^') {
            self.position += 1;
            true
        } else {
            false
        };
        let set = self.parse_intersection()?;
        if self.peek() != Some(']') {
            return None;
        }
        self.position += 1;
        if negated {
            Some(complement_set(&set))
        } else {
            Some(set)
        }
    }

    fn parse_intersection(&mut self) -> Option<IntervalSet> {
        let mut result = self.parse_union()?;
        while self.peek() == Some('&') && self.peek_at(1) == Some('&') {
            self.position += 2;
            let side = self.parse_union()?;
            result = intersect_sets(&result, &side);
        }
        Some(result)
    }

    fn parse_union(&mut self) -> Option<IntervalSet> {
        let mut result: IntervalSet = Vec::new();
        let mut first = true;
        while let Some(current) = self.peek() {
            if current == ']' && !first {
                break;
            }
            if current == '&' && self.peek_at(1) == Some('&') {
                break;
            }
            let item = self.parse_item(first)?;
            result = union_sets(result, item);
            first = false;
        }
        Some(result)
    }

    fn parse_item(&mut self, _first: bool) -> Option<IntervalSet> {
        // A nested character class.
        if self.peek() == Some('[') && self.peek_at(1) != Some(':') {
            return self.parse_outer();
        }
        let start = self.parse_class_char()?;
        if self.peek() == Some('-') {
            let after_dash = self.peek_at(1)?;
            if after_dash != ']' {
                self.position += 1;
                let end = self.parse_class_char()?;
                if start > end {
                    return None;
                }
                return Some(vec![(start, end)]);
            }
        }
        Some(vec![(start, start)])
    }

    fn parse_class_char(&mut self) -> Option<u32> {
        let current = self.peek()?;
        self.position += 1;
        if current != '\\' {
            return Some(current as u32);
        }
        let escaped = self.peek()?;
        self.position += 1;
        match escaped {
            'd' | 'D' | 's' | 'S' | 'w' | 'W' | 'p' | 'P' => None,
            'n' => Some(10),
            'r' => Some(13),
            't' => Some(9),
            'f' => Some(12),
            'v' => Some(11),
            'a' => Some(7),
            'e' => Some(27),
            '0' => Some(0),
            'x' | 'u' | 'U' => {
                if self.peek() == Some('{') {
                    self.position += 1;
                    let mut value = String::new();
                    while let Some(c) = self.peek() {
                        self.position += 1;
                        if c == '}' {
                            break;
                        }
                        value.push(c);
                    }
                    u32::from_str_radix(&value, 16).ok()
                } else {
                    let digits = match escaped {
                        'x' => 2,
                        'u' => 4,
                        _ => 8,
                    };
                    let mut value = String::new();
                    for _ in 0..digits {
                        value.push(self.peek()?);
                        self.position += 1;
                    }
                    u32::from_str_radix(&value, 16).ok()
                }
            }
            other => Some(other as u32),
        }
    }
}

fn class_token_is_empty(token: &[char]) -> Option<bool> {
    // Set operations beyond plain intersections, and class-like
    // escapes or POSIX classes, are left to the regex crate.
    let text: String = token.iter().collect();
    if text.contains("[:") || text.contains("--") {
        return None;
    }
    let mut parser = ClassParser {
        chars: token.to_vec(),
        position: 0,
    };
    let set = parser.parse_outer()?;
    if parser.position != token.len() {
        return None;
    }
    Some(set.is_empty())
}
