type IntervalSet = Vec<(u32, u32)>;

fn normalize(mut intervals: IntervalSet) -> IntervalSet {
    intervals.sort();
    let mut result: IntervalSet = Vec::new();
    for (start, end) in intervals {
        if start > end {
            continue;
        }
        if let Some((_, last_end)) = result.last_mut() {
            if start <= *last_end || start == *last_end + 1 {
                if end > *last_end {
                    *last_end = end;
                }
                continue;
            }
        }
        result.push((start, end));
    }
    result
}

fn union_sets(first: IntervalSet, second: IntervalSet) -> IntervalSet {
    let mut all = first;
    all.extend(second);
    normalize(all)
